-- ========================
-- 演示公告
-- yi-demo 的 DemoNotice 使用这张表。不用演示模块时可以不执行。
-- ========================

CREATE TABLE demo_notice (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title         VARCHAR(128) NOT NULL,
    content       VARCHAR(500),
    pinned        BOOLEAN      NOT NULL DEFAULT FALSE,
    created_time  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    modified_time TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_time  TIMESTAMP,
    is_deleted    BOOLEAN      NOT NULL DEFAULT FALSE
);

COMMENT ON TABLE demo_notice IS '演示公告表';
COMMENT ON COLUMN demo_notice.id IS '主键';
COMMENT ON COLUMN demo_notice.title IS '标题';
COMMENT ON COLUMN demo_notice.content IS '正文';
COMMENT ON COLUMN demo_notice.pinned IS '是否置顶';
COMMENT ON COLUMN demo_notice.created_time IS '创建时间';
COMMENT ON COLUMN demo_notice.modified_time IS '修改时间';
COMMENT ON COLUMN demo_notice.deleted_time IS '删除时间';
COMMENT ON COLUMN demo_notice.is_deleted IS '是否删除 false:否 true:是';

CREATE TRIGGER trg_demo_notice_modified_time
    BEFORE UPDATE ON demo_notice
    FOR EACH ROW
    EXECUTE PROCEDURE touch_modified_time();
